export type EnglishLevel = "principiante" | "intermedio" | "avanzado";
export type EnglishLessonType = "vocab" | "listen" | "pron" | "reading" | "quiz";
export type EnglishVocabCard = { emoji: string; en: string; ipa: string; es: string };
export type EnglishExercise = { audio: string; options: [string, string, string]; correct: number };
export type EnglishPhrase = { en: string; es: string };
export type EnglishQuestion = { q: string; options: [string, string, string, string]; correct: number; explain: string };
export type EnglishContext = { type: EnglishLessonType; listened: Set<string>; completed: number; answered: Set<number>; practiced: number; marked: Set<number> };
export type EnglishCheck = { desc: string; test: (ctx: EnglishContext) => boolean };
export type EnglishLesson = {
  id: string; type: EnglishLessonType; icon: string; xp: number; minutes: number; title: string; desc: string; level: EnglishLevel;
  objectives: [string, string, string]; dax: { hint: string; explain: string; example: string };
  intro?: string; vocab?: EnglishVocabCard[]; exercises?: EnglishExercise[]; phrases?: EnglishPhrase[];
  content?: string; keyPoints?: [string, string, string]; questions?: EnglishQuestion[]; checks?: [EnglishCheck];
};
export type EnglishModule = { id: string; title: string; minutes: number; goal: string; level: EnglishLevel; photo: string; photoAlt: string; lessons: EnglishLesson[] };

type VocabSpec = { title: string; desc: string; cards: EnglishVocabCard[]; hint: string; analogy: string; example: string; threshold: number; intro?: string };
type ListenSpec = { title: string; desc: string; exercises: EnglishExercise[]; hint: string; analogy: string; example: string; intro?: string };
type PronSpec = { title: string; desc: string; phrases: EnglishPhrase[]; hint: string; analogy: string; example: string; threshold: number; intro?: string };
type ReadingSpec = { title: string; desc: string; explanation: string; pattern: string; points: [string, string, string]; note: string; tip: string; hint: string; analogy: string; example: string };
type ModuleSpec = { title: string; level: EnglishLevel; goal: string; photo: string; photoAlt: string; vocab: VocabSpec[]; listen: ListenSpec[]; pron: PronSpec[]; reading: ReadingSpec[]; quiz: EnglishQuestion[] };

