    title: "Present Continuous", level: "intermedio", photo: photos.city, photoAlt: "Personas caminando por una calle de la ciudad", goal: "Describir acciones en progreso y distinguirlas de hábitos con presente simple.", vocab: [], pron: [], reading: [
      { title: "Actions Happening Now", desc: "Forma presente continuo con be y verbo terminado en -ing.", explanation: "Usa present continuous para acciones que ocurren ahora o alrededor del momento actual: sujeto + am/is/are + verbo-ing.", pattern: "I am working now.\nShe is reading a message.\nThey are waiting outside.", points: ["Usa am con I, is con he/she/it y are con you/we/they.", "El verbo principal añade -ing.", "Now y at the moment suelen señalar una acción en progreso."], note: "Error frecuente: omitir be y decir I working; la forma necesita I am working.", tip: "Escucha primero el auxiliar be y después identifica el verbo con -ing.", hint: "Comprueba quién es el sujeto antes de elegir am, is o are.", analogy: "El presente continuo es como una transmisión en vivo: la acción sucede ahora.", example: "I am studying now. (Estoy estudiando ahora.)" },
      { title: "Habits or Actions Now?", desc: "Contrasta rutinas permanentes con acciones temporales en progreso.", explanation: "Present simple describe hábitos; present continuous describe lo que sucede ahora o temporalmente. La diferencia cambia el significado del mismo verbo.", pattern: "I work every weekday.\nI'm working from home this week.", points: ["Every day suele acompañar rutinas en presente simple.", "Now y this week pueden marcar una acción actual o temporal.", "Algunos verbos de estado normalmente no se usan en continuo en este nivel."], note: "No confundas una rutina (She works) con una actividad actual (She is working).", tip: "Busca expresiones de frecuencia o de tiempo actual antes de escoger el tiempo verbal.", hint: "Decide si la frase describe algo habitual o algo que está ocurriendo en este periodo.", analogy: "El presente simple es un calendario; el continuo es una foto del momento.", example: "She's working from home this week. (Está trabajando desde casa esta semana.)" },
    ], listen: [{ title: "Now or Usually?", desc: "Distingue hábitos de acciones que ocurren en este momento.", exercises: [
      { audio: "She is talking on the phone.", options: ["She is talking on the phone.", "She talks on the phone.", "She is walking on the phone."], correct: 0 }, { audio: "I usually take the train.", options: ["I usually take the train.", "I'm taking the train now.", "I used to take the train."], correct: 0 }, { audio: "They are waiting outside.", options: ["They were waiting outside.", "They are waiting outside.", "They wait outside every day."], correct: 1 }, { audio: "He works every Saturday.", options: ["He is working right now.", "He worked last Saturday.", "He works every Saturday."], correct: 2 }, { audio: "We are having lunch at the moment.", options: ["We have lunch at noon.", "We are having lunch at the moment.", "We had lunch a moment ago."], correct: 1 },
    ], hint: "Usually y every Saturday indican hábito; at the moment apunta a una acción en curso.", analogy: "Be + -ing es una señal visual de una cámara encendida durante la acción.", example: "They're waiting right now. (Están esperando ahora mismo.)" }],
